CREATE OR REPLACE PROCEDURE sp(
  para_Vice_President_Vote NUMBER,
  para_Registration_integer VARCHAR2,
  para_President_Vote NUMBER,
  para_Class_President_Vote NUMBER
) IS
  v_max_class_senator NUMBER;
BEGIN
  FOR rec IN (
    SELECT * FROM Voting_record
    WHERE Vice_President_Vote >= para_Vice_President_Vote
    FOR UPDATE
  ) LOOP
    IF v_max_class_senator IS NULL OR rec.Class_Senator_Vote > v_max_class_senator THEN
      v_max_class_senator := rec.Class_Senator_Vote;
    END IF;

    IF INSTR(rec.Registration_integer, 'prefix_') = 1 THEN
      UPDATE Voting_record
         SET President_Vote = para_President_Vote
       WHERE CURRENT OF rec;
    ELSIF rec.Class_President_Vote < para_Class_President_Vote THEN
      DELETE FROM Voting_record WHERE CURRENT OF rec;
    ELSE
      UPDATE Voting_record
         SET President_Vote = para_President_Vote * 2
       WHERE CURRENT OF rec;
    END IF;
  END LOOP;

  DELETE FROM Voting_record
   WHERE Registration_integer = 'prefix_' || para_Registration_integer;

  INSERT INTO Voting_record (Vice_President_Vote, Registration_integer, President_Vote, Class_Senator_Vote)
  VALUES (para_Vice_President_Vote + 1, 'prefix_' || para_Registration_integer, para_President_Vote, NVL(v_max_class_senator, 0) + 1);
END sp;

